import{createPendulumExperiment,PENDULUM_DEFAULTS,comparePendulumTrials}from'./pendulum-model.js';
import{drawPendulum,drawPendulumGraph,pendulumBob}from'./pendulum-draw.js';
const SOURCE='https://openstax.org/books/university-physics-volume-1/pages/15-4-pendulums';
const LABELS={length:'길이',mass:'질량',angle:'놓는 각도'};
export function pendulumMarkup(){return `<div class="pendulum-lab"><p class="pendulum-intro">길이·질량·각도를 바꿔 놓아 보세요. 세 번 왕복하는 시간을 재고, 지난 실험과 비교해요.</p><div class="pendulum-layout"><section class="pendulum-observation" aria-label="진자와 센서"><canvas id="pendulum-rig" width="720" height="390" role="img" aria-label="진자의 줄 길이와 놓는 각도. 추를 끌거나 옆 슬라이더로 조건을 바꿀 수 있어요"></canvas><div class="pendulum-readout"><div><span>센서로 잰 한 왕복</span><strong id="pendulum-period">—</strong><small>초 · 3왕복 평균</small></div><p id="pendulum-sensor">측정 대기</p></div><p id="pendulum-status" class="pendulum-status" role="status" aria-live="polite">조건을 고른 뒤 추 놓기를 눌러요</p></section><section class="pendulum-controls" aria-label="실험 조건"><h3>1. 조건을 골라요</h3>${[['length','줄 길이','m',.25,2,.01,1],['mass','추 질량','kg',.1,1,.05,.5],['angle','놓는 각도','°',5,60,1,10]].map(([id,label,unit,min,max,step,value])=>`<label for="pendulum-${id}"><span>${label}<output id="pendulum-${id}-value"></output></span><input id="pendulum-${id}" type="range" min="${min}" max="${max}" step="${step}" value="${value}" aria-label="${label} (${unit})"></label>`).join('')}<p class="pendulum-small">길이는 받침점부터 추 중심까지 · 조건을 바꾸면 현재 측정은 처음부터 시작해요</p><h3>2. 놓고 재봐요</h3><div class="pendulum-actions"><button id="pendulum-start" class="primary">추 놓기 · 3왕복 측정</button><button id="pendulum-pause" disabled>일시정지</button><button id="pendulum-reset">같은 조건 다시</button></div><label class="pendulum-speed" for="pendulum-speed">재생 속도<select id="pendulum-speed"><option value="1">1배</option><option value="2">2배</option><option value="0.5">0.5배</option></select></label><p class="pendulum-small">속도는 보기만 바꿔요. 센서는 시뮬레이션 시간을 재요.</p><details class="pendulum-challenge"><summary>선택 도전 · 한 왕복 2초 만들기</summary><p>측정값을 2.00초에서 0.03초 미만 차이로 맞춰요. 길이를 바꿔 다시 놓아 보세요.</p><p id="pendulum-challenge-result">먼저 한 번 측정해봐요</p></details></section></div><section class="pendulum-analysis"><h3>3. 지난 실험과 비교해요</h3><div class="pendulum-legend"><span>━ 현재 실험</span><span>┄ 선택한 기준</span></div><canvas id="pendulum-graph" width="720" height="270" role="img" aria-label="시간에 따른 진자 각도. 초록 실선은 현재 실험, 갈색 점선은 선택한 기준"></canvas><p id="pendulum-comparison">한 번 측정하면 이곳에 기록돼요. 조건을 하나만 바꾸어 비교해보세요.</p><div id="pendulum-history" class="pendulum-history" aria-label="최근 실험 기록, 눌러서 비교 기준 선택"></div><p class="pendulum-small">최근 8회 · 실험실을 닫아도 이번 방문 중에는 유지돼요. 새로고침하면 지워져요.</p><details class="pendulum-detail"><summary>에너지와 수식 더 보기</summary><div class="pendulum-energy" aria-label="운동 에너지와 위치 에너지"><span id="pendulum-kinetic-bar"></span><span id="pendulum-potential-bar"></span></div><p id="pendulum-energy-values"></p><p id="pendulum-theory"></p><p>운동식 θ″ = −(g/L) sin θ · 작은각도 근사 T₀ = 2π√(L/g)<br>운동 에너지 ½mL²ω² · 위치 에너지 mgL(1−cos θ)</p><p class="pendulum-small">큰 각도에서는 근사값보다 주기가 길어져요. 이 차이는 측정 실수가 아니라 작은각도 가정의 한계예요. 질량은 운동식에서 소거되지만 에너지의 크기는 바꿔요.</p></details><details class="pendulum-detail"><summary>모형의 가정과 출처</summary><p>공기 저항·마찰 없이, 늘어나지 않는 질량 없는 줄과 점으로 보는 추, 고정된 받침점을 가정해요. 중력은 9.81 m/s²로 일정해요. 그림의 추 크기는 설명용이며 길이는 중심까지예요.</p><p>중앙을 같은 방향으로 처음 지날 때 센서가 시작되고, 다음 세 번 통과할 때까지의 시간을 3으로 나눠요. 비선형 운동식을 수치 계산한 시뮬레이션 측정이며 실제 장비의 오차나 독립적인 현실 실험 결과는 아니에요.</p><a href="${SOURCE}" target="_blank" rel="noopener noreferrer">OpenStax · 진자의 운동과 작은각도 근사</a></details></section></div>`;}
export function createPendulumLab({ui,document:doc=globalThis.document,window:win=globalThis.window,requestFrame=fn=>requestAnimationFrame(fn),cancelFrame=id=>cancelAnimationFrame(id)}={}){
 let live=null,settings={...PENDULUM_DEFAULTS},history=[],referenceId=null,sequence=0;
 const $=id=>doc.querySelector('#'+id);
 function close(){if(!live)return;const old=live;live=null;settings=old.model.snapshot().settings;old.model.dispose();if(old.frame!==null)cancelFrame(old.frame);for(const[node,event,fn]of old.listeners)node?.removeEventListener?.(event,fn);for(const[node,key]of old.handlers)node[key]=null;try{if(old.pointer!==null)$('pendulum-rig')?.releasePointerCapture(old.pointer);}catch{}old.pointer=null;}
 function open(){if(live)return false;return ui.workshop('초파리 선생님의 진자 실험실',pendulumMarkup(),()=>{
  const model=createPendulumExperiment(settings),session={model,frame:null,last:null,speed:1,recorded:false,pointer:null,listeners:[],handlers:[]};live=session;const current=()=>live===session,bind=(id,key,fn)=>{const node=$(id);node[key]=(...args)=>{if(current())fn(...args);};session.handlers.push([node,key]);},listen=(node,event,fn)=>{node?.addEventListener?.(event,fn);session.listeners.push([node,event,fn]);};
  const rig=$('pendulum-rig'),graph=$('pendulum-graph'),rigContext=rig.getContext('2d'),graphContext=graph.getContext('2d');
  function reference(){return history.find(r=>r.id===referenceId)??null;}
  function historyView(){const host=$('pendulum-history');host.replaceChildren();for(const r of [...history].reverse()){const b=doc.createElement('button');b.type='button';b.setAttribute('aria-pressed',String(r.id===referenceId));b.textContent=`${r.id}회 · ${r.settings.length.toFixed(2)} m / ${(r.settings.mass*1000).toFixed(0)} g / ${r.settings.angle}° → ${r.period.toFixed(3)}초`;b.onclick=()=>{if(!current())return;referenceId=r.id;historyView();render();};host.append(b);}}
  function render(){if(!current())return;const s=model.snapshot(),ref=reference();drawPendulum(rigContext,s);drawPendulumGraph(graphContext,s,ref,graph.getBoundingClientRect().width||720);for(const key of['length','mass','angle']){$('pendulum-'+key).value=String(s.settings[key]);$('pendulum-'+key+'-value').textContent=key==='length'?s.settings.length.toFixed(2)+' m':key==='mass'?(s.settings.mass*1000).toFixed(0)+' g':s.settings.angle+'°';}
   $('pendulum-period').textContent=s.period===null?'—':s.period.toFixed(3);$('pendulum-sensor').textContent=`${s.elapsed.toFixed(2)} s 경과 · ${s.crossings.length?`${s.periods.length}/3 왕복 감지`:'첫 중앙 통과 대기'}`;
   $('pendulum-start').textContent=s.phase==='paused'?'계속 측정하기':s.phase==='complete'?'측정 완료':'추 놓기 · 3왕복 측정';$('pendulum-start').disabled=['running','complete'].includes(s.phase);$('pendulum-pause').disabled=s.phase!=='running';
   $('pendulum-challenge-result').textContent=s.period===null?'측정을 마치면 결과가 나와요':s.challengePassed?'성공! 한 왕복을 2초에 맞췄어요':`목표와 ${Math.abs(s.period-2).toFixed(3)}초 차이 · ${s.period>2?'줄을 조금 줄여':'줄을 조금 늘려'} 다시 놓아볼까요?`;
   const c=comparePendulumTrials(ref,s);$('pendulum-comparison').textContent=c?`기준 ${ref.id}회와 비교: ${c.changed.length?c.changed.map(k=>LABELS[k]).join('·')+' 변경':'같은 조건'} · 주기 ${c.difference>=0?'+':''}${c.difference.toFixed(3)}초 (${c.percent>=0?'+':''}${c.percent.toFixed(2)}%). ${c.changed.length>1?'여러 조건을 바꿔서 어느 조건 때문인지는 따로 비교해야 해요.':c.changed[0]==='mass'?'질량만 바꿔도 주기는 같아요. 접힌 에너지 값도 비교해보세요.':!c.changed.length?'무작위 오차를 넣지 않은 모형이라 같은 조건의 결과는 같아요.':'다른 조건을 유지한 비교예요.'}`:ref?`기준 ${ref.id}회: ${ref.period.toFixed(3)}초. 한 조건을 바꾸고 다시 측정하면 차이를 보여줘요.`:'첫 실험을 끝내면 기준 기록이 생겨요. 조건을 하나만 바꿔 비교해보세요.';
   const e=s.energy;$('pendulum-kinetic-bar').style.width=(e.kinetic/e.total*100)+'%';$('pendulum-potential-bar').style.width=(e.potential/e.total*100)+'%';$('pendulum-energy-values').textContent=`초록 운동 ${e.kinetic.toFixed(3)} J · 금색 위치 ${e.potential.toFixed(3)} J · 합 ${e.total.toFixed(3)} J${ref?` · 기준 ${ref.id}회 합 ${ref.energy.total.toFixed(3)} J`:''}`;$('pendulum-theory').textContent=`작은각도 근사 ${s.smallAnglePeriod.toFixed(3)}초${s.period===null?'':` · 측정 ${s.period.toFixed(3)}초 · 근사와 ${s.approximationDifferencePercent.toFixed(3)}% 차이`}`;
  }
  function stopFrame(){if(session.frame!==null)cancelFrame(session.frame);session.frame=null;session.last=null;}
  function pause(){if(!current())return;if(model.pause()){$('pendulum-status').textContent='잠시 멈췄어요. 계속 측정하면 같은 실험을 이어가요';stopFrame();render();}}
  function frame(now){if(!current())return;session.frame=null;if(session.last!==null)model.advance(Math.max(0,Math.min(.25,(now-session.last)/1000))*session.speed);session.last=now;const s=model.snapshot();if(s.phase==='complete'&&!session.recorded){session.recorded=true;const result={...s,id:++sequence};history.push(result);if(history.length>8)history.shift();if(!history.some(x=>x.id===referenceId))referenceId=history[0].id;historyView();$('pendulum-status').textContent=`측정 완료! 세 왕복 ${s.sensorTime.toFixed(3)}초 ÷ 3 = ${s.period.toFixed(3)}초. 조건을 바꿔 다시 비교해요`;stopFrame();}render();if(s.phase==='running')session.frame=requestFrame(frame);}
  function reset(next=model.snapshot().settings){stopFrame();model.reset(next);session.recorded=false;$('pendulum-status').textContent='새 조건 준비 완료. 추 놓기를 눌러 측정해요';render();}
  for(const key of['length','mass','angle'])bind('pendulum-'+key,'oninput',()=>reset({...model.snapshot().settings,[key]:Number($('pendulum-'+key).value)}));
  bind('pendulum-start','onclick',()=>{if(model.start()){session.last=null;$('pendulum-status').textContent='센서가 같은 방향의 중앙 통과를 재요. 첫 통과 뒤 세 왕복을 기다려요';render();session.frame=requestFrame(frame);}});bind('pendulum-pause','onclick',pause);bind('pendulum-reset','onclick',()=>reset());bind('pendulum-speed','onchange',()=>{session.speed=Number($('pendulum-speed').value)||1;});
  const point=e=>{const r=rig.getBoundingClientRect();return{x:(e.clientX-r.left)*720/r.width,y:(e.clientY-r.top)*390/r.height};};
  bind('pendulum-rig','onpointerdown',e=>{if(e.button!==0||session.pointer!==null)return;const p=point(e),bob=pendulumBob(model.snapshot());if(Math.hypot(p.x-bob.x,p.y-bob.y)>42)return;e.preventDefault();session.pointer=e.pointerId;rig.setPointerCapture?.(e.pointerId);reset();});
  bind('pendulum-rig','onpointermove',e=>{if(e.pointerId!==session.pointer)return;e.preventDefault();const p=point(e),angle=Math.atan2(p.x-360,p.y-57)*180/Math.PI;reset({...model.snapshot().settings,angle});});
  const release=()=>{const id=session.pointer;session.pointer=null;try{if(id!==null)rig.releasePointerCapture?.(id);}catch{}};bind('pendulum-rig','onpointerup',release);bind('pendulum-rig','onpointercancel',release);bind('pendulum-rig','onlostpointercapture',()=>{session.pointer=null;});listen(win,'resize',()=>{release();render();});listen(win,'blur',()=>{release();pause();});listen(doc,'visibilitychange',()=>{if(doc.hidden){release();pause();}});
  doc.fonts?.load('700 22px "Dormi Gentle Pen"','진자').then(()=>{if(current())render();}).catch(()=>{});historyView();render();return close;
 },{kind:'school-workshop pendulum-workshop',closeLabel:'나가기'});}
 return{open,close};
}
